R=[
(2265,"बोन कुकीज़","बोन कुकीज़ की यह रेसिपी ओस्सा दे मॉर्टी या \"मृतकों की हड्डियों की कुकीज़\" नामक एक पुरानी इटैलियन रेसिपी से ली गई है। इन्हें 1 नवंबर को डे ऑफ़ द डेड पर परोसा जाता है, जो इस दुनिया से जा चुके लोगों की याद में मनाया जाने वाला उत्सव है। पिसे बादाम होने के बावजूद बोन कुकीज़ किडनी के अनुकूल हैं, प्रति कुकी केवल 22 mg फॉस्फोरस होता है।","12","2 कुकीज़",
["2 अंडों का सफ़ेद भाग","1-1/4 कप सफ़ेद मैदा","1-1/4 कप दानेदार चीनी","1/2 कप ब्राउन शुगर","1/2 कप बादाम, पिसे हुए","1 बड़ा चम्मच नींबू का रस","1 छोटा चम्मच नींबू का ज़ेस्ट","1 छोटा चम्मच दालचीनी","1 बड़ा चम्मच पानी","1/2 कप पिसी चीनी (पाउडर शुगर)"],
["अंडे के सफ़ेद भाग को कड़े शिखर बनने तक फेंटें।","एक बड़े कटोरे में मैदा, सफ़ेद और ब्राउन शुगर, बादाम, नींबू का रस, नींबू का ज़ेस्ट और दालचीनी मिलाएँ; फेंटे हुए अंडे के सफ़ेद भाग को धीरे से मिलाएँ और भुरभुरा होने तक मिलाएँ। पानी डालकर मिलाएँ।","आटे का गोला बनाएँ, ढकें, प्लास्टिक रैप में लपेटें और 20 मिनट के लिए ठंडा करें।","ओवन को 350° F पर पहले से गरम करें। बेकिंग शीट पर चिकनाई लगाएँ।","ठंडे किए हुए आटे को 4 हिस्सों में बाँटें। हाथों पर मैदा लगाएँ और हर हिस्से को 1″ मोटी रस्सी (लगभग 12″ लंबी) की तरह बेलें। हर रस्सी को 2″ के टुकड़ों में काटें और उंगली के आकार के, लगभग 1/2″ मोटे होने तक बेलें।","बेकिंग शीट पर रखें और 15 से 18 मिनट बेक करें।","ठंडा होने दें, फिर ऊपर से पिसी चीनी में लपेटकर परत चढ़ाएँ।"],
["ठंडा होने पर कुकीज़ सख़्त और कुरकुरी हो जाएँगी।","मधुमेह आहार के लिए अनुशंसित मात्रा एक कुकी है (16 ग्राम कार्बोहाइड्रेट)।"],
["1 स्टार्च","1 उच्च कैलोरी"]),
(2266,"चिकन पेस्टो पास्ता","इस चिकन पेस्टो पास्ता मुख्य व्यंजन की रेसिपी में पेस्टो वह सामग्री है जो सारे स्वादों को एक साथ जोड़ती है।","8","1 कप",
["10 ऑउंस पेने पास्ता","1-1/4 पाउंड बिना हड्डी और बिना त्वचा वाला चिकन ब्रेस्ट","1 छोटा प्याज़","1 बड़ी हरी शिमला मिर्च","1 बड़ी लाल शिमला मिर्च","3 लहसुन की कलियाँ","2 बड़े चम्मच जैतून का तेल","2 बड़े चम्मच बालसमिक सिरका","1/2 छोटा चम्मच नमक (वैकल्पिक)","1/4 छोटा चम्मच काली मिर्च","1/3 कप बेसिल पेस्टो"],
["पास्ता को पैकेट के निर्देशों के अनुसार बिना नमक डाले पकाएँ। पानी निथारकर एक तरफ़ रख दें।","चिकन को निवाले के आकार के टुकड़ों में काटें। प्याज़ और शिमला मिर्च को छोटे टुकड़ों में काटें। लहसुन की कलियों को बारीक काटें।","एक बड़ी कड़ाही में प्याज़ और शिमला मिर्च को 1 बड़े चम्मच जैतून के तेल में नरम होने तक भूनें। एक और बड़ा चम्मच जैतून का तेल, लहसुन और चिकन के टुकड़े डालें और चिकन के पकने तक पकाएँ, लगभग 5 से 7","मिनट।","आँच धीमी कर दें और पका हुआ पास्ता, बालसमिक सिरका, नमक और काली मिर्च डालें। अच्छी तरह मिलने तक चलाएँ।","पेस्टो डालें, चलाएँ और परोसने से पहले गरम करें।"],
["फ़ाइबर की मात्रा बढ़ाने के लिए साबुत गेहूँ का पास्ता इस्तेमाल करें।","स्वादिष्ट बदलाव के लिए चिकन की जगह टर्की या झींगे इस्तेमाल करें।","कम प्रोटीन वाले आहार के लिए चिकन को घटाकर 12 ऑउंस कर दें (प्रति सर्विंग 17 ग्राम प्रोटीन)।"],
["2-1/2 प्रोटीन","2 स्टार्च","1 सब्ज़ी, मध्यम पोटैशियम"]),
(2269,"लहसुन-अदरक वाला बैंगन","डायलिसिस आहार पर होने का मतलब यह नहीं कि आपको फीका खाना खाना पड़े। लहसुन-अदरक वाले बैंगन की यह किडनी के अनुकूल रेसिपी एशियाई शैली से प्रेरित व्यंजन है, जिसमें कई स्वादिष्ट, किडनी के अनुकूल सामग्रियों को एक साथ स्टर-फ्राई करके लाजवाब स्वाद तैयार किया जाता है। ढेर सारी सब्ज़ियाँ और मसाले इस साइड डिश को खास बना देते हैं।","4","3/4 कप",
["2 कप चाइनीज़ बैंगन","2 छोटे चम्मच बारीक कटा अदरक","2 लहसुन की कलियाँ","1/4 कप ताज़ी तुलसी","2 बड़े चम्मच तिल का तेल","1/2 कप ताज़ी मशरूम के टुकड़े","1 कप मूँग के अंकुर","1/4 छोटा चम्मच लाल मिर्च के फ्लेक्स","1 बड़ा चम्मच होइसिन सॉस"],
["बैंगन को 1-1/2 इंच लंबे टुकड़ों में काटें। लहसुन की कलियों को बारीक काटें। तुलसी को काट लें।","एक बड़ी कड़ाही में तिल का तेल गरम करें। बैंगन, अदरक, लहसुन, मशरूम और अंकुर डालें। तेज़-मध्यम आँच पर बैंगन के नरम होने तक स्टर-फ्राई करें, 4-6 मिनट।","बैंगन में तुलसी, लाल मिर्च के फ्लेक्स और होइसिन सॉस डालें। 1-2 मिनट और पकाते रहें। आँच से उतारें और परोसें।"],
["अगर चाइनीज़ बैंगन उपलब्ध न हो, तो सामान्य बैंगन इस्तेमाल करें। इसे 1 इंच के टुकड़ों में काटें (छिलके सहित)।","होइसिन सॉस सोयाबीन के पेस्ट से बना उत्पाद है जो ज़्यादातर किराना दुकानों के विशेष खाद्य सेक्शन में मिलता है। 1 बड़े चम्मच होइसिन सॉस में 250 mg सोडियम होता है (प्रति सर्विंग 63 mg)। Sun Luck ब्रांड देखें, जो सिएटल, वॉशिंगटन की Sun Luck से उपलब्ध है। बहुत थोड़ी सी मात्रा भी ढेर सारा स्वाद देती है!"],
["1 सब्ज़ी, मध्यम पोटैशियम","1-1/2 वसा"]),
(2272,"प्याज़ हर्ब सीज़निंग ब्लेंड","प्याज़ और लहसुन पाउडर, पेपरिका, अजमोद (पार्सले) और तुलसी, ये 5 सामग्रियाँ हैं जो इस ज़ायकेदार प्याज़ हर्ब सीज़निंग ब्लेंड को बनाती हैं।","12","1 बड़ा चम्मच",
["1 बड़ा चम्मच प्याज़ पाउडर","1 बड़ा चम्मच पेपरिका","1 बड़ा चम्मच सूखा अजमोद (पार्सले)","2 छोटे चम्मच लहसुन पाउडर","1 छोटा चम्मच पिसी तुलसी"],
["सामग्री को एक जार में डालें और हिलाकर मिला लें।","खाना पकाने में इस्तेमाल करने तक रखें, या मेज़ पर इस्तेमाल करने के लिए शेकर में डाल दें।"],
["बड़े छेदों वाला टेबल शेकर इस्तेमाल करें।"],
["कोई नहीं"]),
(2273,"भुना हुआ दालचीनी अनानास","DaVita की आहार विशेषज्ञ एस्थर की भुने हुए दालचीनी अनानास की रेसिपी मिठाई, नाश्ते या स्नैक के लिए स्वादिष्ट है।","6","अनानास की 1 फाँक",
["1 ताज़ा अनानास","2 बड़े चम्मच मक्खन","1/4 कप शहद","1 बड़ा चम्मच ताज़ा नींबू (लाइम) का रस","1 छोटा चम्मच दालचीनी","लाइम ज़ेस्ट (वैकल्पिक)"],
["ओवन को 425° F पर पहले से गरम करें।","अनानास के दोनों सिरे काट दें। छीलकर बीच का कड़ा हिस्सा निकालें और एक-एक इंच की छह फाँकों में काटें।","किनारे वाली बेकिंग शीट को फ़ॉइल से ढकें और उस पर नॉन-स्टिक स्प्रे लगाएँ।","मक्खन पिघलाएँ और एक छोटे कटोरे में शहद, नींबू (लाइम) के रस और दालचीनी के साथ मिलाएँ।","अनानास की फाँकों को समतल हिस्सा नीचे रखकर बेकिंग शीट पर रखें। आधा सॉस फाँकों पर बराबर ब्रश से लगाएँ। फाँकों को पलटें और बचे सॉस के साथ यही दोहराएँ।","बेकिंग शीट को ओवन में रखें और अनानास को 10 मिनट भूनें। फाँकों को पलटें और अनानास के हल्का भूरा और कैरमेलाइज़ होने तक 15 मिनट और भूनें।","थोड़ा ठंडा होने दें, ऊपर से लाइम ज़ेस्ट डालें और गरमागरम परोसें।"],
["अनानास कितने पके हैं, यह बाहरी रंग से पता नहीं चलता। अनानास पूरी तरह पकने पर तोड़े जाते हैं और उसके बाद और नहीं पकते। इसके बजाय, भरी हुई हरी पत्तियों, सख़्त छिलके और मीठी खुशबू वाले अनानास देखें।","शहद की जगह ब्राउन शुगर इस्तेमाल की जा सकती है।","भुना हुआ अनानास अपने आप में एक ट्रीट है, लेकिन और भी लज़ीज़ किडनी के अनुकूल मिठाई के लिए इसे गैर-डेयरी आइसक्रीम के साथ या ऊपर घर की बनी व्हिप्ड क्रीम की एक डली के साथ परोसें।"],
["1 फल, मध्यम पोटैशियम","1 उच्च कैलोरी","1 वसा"]),
(2274,"एप्पल पाई","DaVita की मिनेसोटा की रीनल आहार विशेषज्ञ अपनी कुछ पसंदीदा क्षेत्रीय रेसिपी साझा करती हैं, जिन्हें डायलिसिस आहार के अनुसार बदला गया है। फॉस्फोरस, पोटैशियम और सोडियम को सीमित करके डायलिसिस के मरीज़ इस स्वादिष्ट एप्पल पाई की रेसिपी का आनंद ले सकते हैं।","8","पाई का 1/8 हिस्सा",
["6 मध्यम सेब","1/2 कप दानेदार चीनी","1 छोटा चम्मच पिसी दालचीनी","6 बड़े चम्मच मक्खन","2-2/3 कप मैदा","1 कप शॉर्टनिंग","6 बड़े चम्मच पानी"],
["ओवन को 425° F पर पहले से गरम करें।","सेबों को छीलें, बीज निकालें और स्लाइस में काटें।","एक बड़े कटोरे में सेब के स्लाइस, चीनी और दालचीनी मिलाएँ। ढककर एक तरफ़ रख दें।","अलग बड़े कटोरे में पेस्ट्री ब्लेंडर से शॉर्टनिंग को मैदे में मिलाएँ। ठंडा पानी एक-एक बड़ा चम्मच करके डालें और आटे के गोले का रूप लेने तक मिलाएँ। अगर ऐसा न हो, तो हाथों से गोला बना लें।","आटे को आधा-आधा बाँटें और एक टुकड़े को बेलन और ज़रूरत के अनुसार अतिरिक्त मैदे की मदद से बेलें। 9″ के पाई पैन में रखें।","सेब की पाई की फ़िलिंग को चलाएँ और पाई शेल में डालें।","1 बड़े चम्मच के टुकड़ों में मक्खन को पाई की फ़िलिंग के चारों ओर बराबर फैलाकर रखें।","आटे के बाकी 1/2 हिस्से को बेलें। इसे सेब की पाई की फ़िलिंग के ऊपर रखें, ध्यान रखें कि पाई के किनारे ढके रहें।","तेज़ चाकू से पाई क्रस्ट के ऊपरी हिस्से के चारों ओर 1” के चार कट लगाएँ ताकि बेक करते समय भाप निकल सके।","पाई को ओवन में जेलीरोल पैन पर रखें ताकि बेक करते समय पाई से निकलने वाला रस उसमें इकट्ठा हो जाए।","क्रस्ट के सुनहरा भूरा होने तक 50 से 60 मिनट बेक करें।"],
["बढ़िया स्वाद वाली एप्पल पाई के लिए सेब की सुझाई गई किस्मों में ये शामिल हैं: फ़ूजी, जोनाथन, जोनागोल्ड, गाला, गोल्डन डिलीशियस, ग्रैनी स्मिथ, पिपिन और वाइनसैप। सबसे अच्छे परिणाम के लिए 2 या 3 किस्मों को मिलाकर देखें।","1 मध्यम सेब को छीलने और बीज निकालने पर 1 कप मिलता है।"],
["1 फल, कम पोटैशियम","2 स्टार्च","6 वसा","1/2 उच्च कैलोरी"]),
(2275,"ब्लैक आइड पी हैश","वर्जीनिया की रीनल आहार विशेषज्ञ निकोल अपनी ब्लैक आइड पी हैश रेसिपी के साथ आपको हर नए साल में शुभकामनाएँ देती हैं। मटर को चावल और अन्य कम पोटैशियम व फॉस्फोरस वाली सामग्रियों के साथ मिलाकर आप नए साल पर या कभी भी ब्लैक-आइड पीज़ का आनंद ले सकते हैं।","6","3/4 कप",
["1 कप जमे हुए ब्लैक आइड पीज़","2 कप पका हुआ सफ़ेद चावल","1 बड़ा चम्मच जैतून का तेल","3 लहसुन की कलियाँ","1 मध्यम लाल शिमला मिर्च","1 छोटा प्याज़","2 डंठल अजवाइन (सेलरी)","2 छोटी गाजर","1/2 कप केल","1 तेज पत्ता","3 ताज़ी थाइम की टहनियाँ","1 कप कम सोडियम वाला चिकन ब्रॉथ","1/2 छोटा चम्मच नमक (वैकल्पिक)","1/4 छोटा चम्मच काली मिर्च"],
["मटर को पिघलने के लिए बाहर रख दें। लहसुन को बारीक काटें; प्याज़ और शिमला मिर्च को काटें; अजवाइन (सेलरी) को स्लाइस में काटें और गाजर को छोटे टुकड़ों में काटें; केल को डंठल से अलग करके काट लें।","एक बड़े पैन में जैतून का तेल गरम करें। लहसुन, प्याज़, शिमला मिर्च, अजवाइन (सेलरी), गाजर, तेज पत्ता और थाइम डालें। मध्यम-धीमी आँच पर खुशबू आने तक भूनें, लगभग 5 मिनट।","केल, ब्लैक-आइड पीज़, नमक और काली मिर्च डालें। हल्के से मिलाएँ।","चिकन ब्रॉथ डालें और लगभग 15 मिनट तक या ब्रॉथ के सूखने तक धीमी आँच पर पकाएँ।","चावल गरम करें; चावल के ऊपर हैश डालें, थाइम की टहनियों या ताज़े अजमोद (पार्सले) से सजाएँ और परोसें।"],
["चाहें तो सारी सामग्री को चावल के साथ धीमी आँच पर पकाकर मिलाकर भी परोस सकते हैं।","चाहें तो तीखा मिर्च सॉस डालें। कम सोडियम वाला ब्रांड चुनें।","अगर उपलब्ध हो, तो जमे हुए मटर की जगह ताज़े पके हुए कम सोडियम वाले मटर इस्तेमाल करें।"],
["1-1/2 स्टार्च","1 सब्ज़ी, मध्यम पोटैशियम"]),
(2277,"मार्गरीटा फ़्रीज़र पाई","ग्रेस की मार्गरीटा फ़्रीज़र पाई का एक टुकड़ा मीठा, नींबू जैसा स्वाद देता है, जो इसे आपकी नई पसंदीदा पाई बना देगा। शानदार स्वाद के साथ-साथ यह 5 सामग्रियों वाली पाई बनाने में बेहद आसान है। इस किडनी के अनुकूल रेसिपी का पालन करके आप अब तक की सबसे बेहतरीन फ़्रीज़र पाई में से एक आज़माएँ।","10","पाई का 1/10 टुकड़ा",
["5 कप कम वसा वाली वनीला बीन आइसक्रीम","6 ऑउंस जमा हुआ लाइमेड कंसन्ट्रेट","2 ताज़े नींबू (लाइम)","1 से 2 बूँद हरा फ़ूड कलर (वैकल्पिक)","1 ग्राहम क्रैकर क्रस्ट"],
["आइसक्रीम को नरम होने के लिए बाहर रख दें; लाइमेड कंसन्ट्रेट को पिघला लें। एक नींबू (लाइम) का छिलका कद्दूकस करें और पाई के मिश्रण में डालने के लिए 2 छोटे चम्मच नाप लें। छिलका निकाले हुए नींबू का रस निकालें और 1 बड़ा चम्मच नाप लें।","एक बड़े कटोरे में नरम की हुई आइसक्रीम, लाइमेड, नींबू का रस और नींबू का ज़ेस्ट मिलाएँ। अच्छी तरह मिलने तक चलाएँ।","मिश्रण को ग्राहम क्रैकर क्रस्ट में डालें। ढकें और सख़्त होने तक फ्रीज़ करें।","पाई को 10 सर्विंग में काटें। हर टुकड़े को ताज़े नींबू (लाइम) के स्लाइस से सजाएँ।"],
["विविधता के लिए लाइम कंसन्ट्रेट की जगह क्रैनबेरी, नींबू या अनानास का जमा हुआ कंसन्ट्रेट इस्तेमाल करें।","अधिक कार्बोहाइड्रेट होने के कारण यह मिठाई मधुमेह वाले लोगों के लिए अनुशंसित नहीं है। हालाँकि, प्रति सर्विंग कार्बोहाइड्रेट घटाकर 26 ग्राम करने के लिए आप ये बदलाव कर सकते हैं: फ़िलिंग बनाकर मिठाई के कपों में जमाएँ और 10 सर्विंग में बाँटें; ग्राहम क्रैकर क्रस्ट हटा दें; और बिना चीनी वाली आइसक्रीम इस्तेमाल करें।"],
["1 स्टार्च","1 दूध","1 उच्च कैलोरी"]),
(2281,"स्ट्रॉबेरी पाई","स्ट्रॉबेरी पाई की किडनी के अनुकूल रेसिपी में कुछ सुकून देने वाली बात है। आज ही आज़माएँ।","8","पाई का 1/8 हिस्सा",
["1 बिना बेक किया पाई शेल, 9” आकार का","4 कप स्ट्रॉबेरी, ताज़ी या जमी हुई","1 कप चीनी","3 बड़े चम्मच कॉर्नस्टार्च","2 बड़े चम्मच नींबू का रस","8 बड़े चम्मच व्हिप्ड टॉपिंग (वैकल्पिक)"],
["पाई शेल को पैकेट पर बताए अनुसार बेक करें। ठंडा होने के लिए एक तरफ़ रख दें।","2 कप स्ट्रॉबेरी को मसलें और चीनी, कॉर्नस्टार्च और नींबू के रस के साथ मिलाएँ।","सामग्री को एक मध्यम सॉसपैन में डालें। मध्यम आँच पर चलाते हुए मिश्रण के गाढ़ा और पारदर्शी होने तक पकाएँ। ठंडा होने दें।","बची हुई स्ट्रॉबेरी को स्लाइस में काटें और ठंडे मिश्रण में मिलाएँ।","ठंडे पाई शेल में डालें। ढककर ठंडा होने तक फ्रिज में रखें।","चाहें तो व्हिप्ड टॉपिंग के साथ परोसें।"],
["अधिक कार्बोहाइड्रेट होने के कारण, मधुमेह होने पर आधी मात्रा की सलाह दी जाती है। कई रेसिपी में चीनी की जगह चीनी के विकल्प इस्तेमाल किए जा सकते हैं। अपनी व्यक्तिगत कार्बोहाइड्रेट ज़रूरतों के आधार पर रेसिपी या सर्विंग साइज़ में बदलाव के बारे में अपने आहार विशेषज्ञ से पूछें।","अगर चीनी की जगह चीनी का विकल्प इस्तेमाल किया जाए, तो कार्बोहाइड्रेट घटकर 20 ग्राम और कार्बोहाइड्रेट चॉइस घटकर एक रह जाती है।"],
["1 स्टार्च","1 फल, मध्यम पोटैशियम","1 उच्च कैलोरी","1 वसा"]),
(2282,"बेक्ड फ्रेंच टोस्ट कस्टर्ड","DaVita की आहार विशेषज्ञ सुसान का बेक्ड फ्रेंच टोस्ट कस्टर्ड उनके DaVita डायलिसिस केंद्र में पसंदीदा है और पूरे परिवार को ज़रूर पसंद आएगा।","4","टोस्ट का 1 स्लाइस",
["4 स्लाइस इटैलियन ब्रेड, 1/2” मोटे कटे हुए","4 कप राइस मिल्क, बिना फ़ोर्टिफ़ाइड","2 कप तरल कम कोलेस्ट्रॉल वाला अंडे का विकल्प","1/2 कप चीनी","4 बड़े चम्मच बिना नमक वाला मार्जरीन, पिघला हुआ","1 छोटा चम्मच बादाम एक्सट्रैक्ट","1 छोटा चम्मच दालचीनी","पिसी चीनी या बिना कैलोरी वाला स्वीटनर, वैकल्पिक"],
["9” x 13” के बेकिंग पैन की तली और किनारों पर मार्जरीन या नॉनस्टिक कुकिंग स्प्रे लगाएँ।","ब्रेड के स्लाइस को पैन की तली में एक परत में सजाएँ।","एक कटोरे में बिना फ़ोर्टिफ़ाइड राइस मिल्क, अंडे का विकल्प, पिघला मार्जरीन, चीनी, बादाम एक्सट्रैक्ट और दालचीनी को फेंटें और ब्रेड के स्लाइस पर डालें।","पैन को प्लास्टिक रैप से ढकें और रात भर फ्रिज में रखें।","ओवन को 350° F पर पहले से गरम करें।","पैन को ओवन में रखें और 40 से 50 मिनट बेक करें, जब तक बीच में डाला गया चाकू साफ़ न निकले।","गरमागरम परोसें।","चाहें तो पिसी चीनी या बिना कैलोरी वाला स्वीटनर छिड़कें।"],
["राइस मिल्क की जगह सादा या फ़्लेवर वाला गैर-डेयरी क्रीमर इस्तेमाल किया जा सकता है। सुसान कहती हैं कि उनके मरीज़ और टीम के साथी कोकोनट क्रीम फ़्लेवर को ज़्यादा पसंद करते हैं।","बादाम एक्सट्रैक्ट की जगह वनीला या नारियल एक्सट्रैक्ट इस्तेमाल किया जा सकता है।","मधुमेह वाले लोग चीनी की जगह Splenda® दानेदार स्वीटनर इस्तेमाल करें ताकि प्रति सर्विंग कार्बोहाइड्रेट घटकर 44 ग्राम और कैलोरी 364 रह जाए, या आधी मात्रा परोसें।","तरल अंडे का विकल्प इस्तेमाल करने की सलाह दी जाती है। अगर इसकी जगह अंडे इस्तेमाल किए जाएँ, तो कैलोरी 550, वसा 24 ग्राम, फॉस्फोरस 263 mg और कोलेस्ट्रॉल 423 mg होता है।"],
["2 प्रोटीन","2 स्टार्च","1 वसा","2-1/2 उच्च कैलोरी"]),
(2283,"हल्दी विनेग्रेट","यह सरल ड्रेसिंग सलाद में कई स्वादों का मेल लाती है और सब्ज़ियों के लिए डिप के रूप में भी इस्तेमाल होती है।","4","2 बड़े चम्मच",
["1/4 कप, और 2 बड़े चम्मच एक्स्ट्रा वर्जिन जैतून का तेल","4 लहसुन की कलियाँ","3 बड़े चम्मच नींबू का रस","2 छोटे चम्मच शहद","2 छोटे चम्मच हल्दी","1/2 छोटा चम्मच डिजॉन सरसों","1/8 छोटा चम्मच काली मिर्च"],
["लहसुन को काट लें। सारी सामग्री को ब्लेंडर या फ़ूड प्रोसेसर में डालें और चिकना होने तक ब्लेंड करें।","बचे हुए को हवाबंद डिब्बे में फ्रिज में रखें।"],
["कहा जाता है कि हल्दी में सूजन-रोधी गुण होते हैं।","सामग्री को मिलाने के लिए आप इमर्शन ब्लेंडर का भी इस्तेमाल कर सकते हैं।","समय बचाने के लिए पहले लहसुन को बारीक काट लें, फिर डिब्बे में सारी सामग्री डालकर अच्छी तरह हिलाएँ।"],
["3 वसा"]),
(2288,"मसालेदार चावल के साथ फ़िश फ्राई","मसालेदार चावल के साथ फ़िश फ्राई किडनी के अनुकूल एक पूरा भोजन है, जो काली मिर्च, जीरे और मिश्रित हर्ब सीज़निंग के स्वाद से भरपूर है।","4","3-1/2 ऑउंस मछली के साथ 1/2 कप चावल",
["1 बड़ा प्याज़","1 कप वनस्पति तेल","1 कप सफ़ेद चावल, बिना पका हुआ","1/2 छोटा चम्मच नमक","2 कप पानी","1 पाउंड जमे हुए कॉड फ़िलेट","1 कप सफ़ेद मैदा","1-1/2 छोटे चम्मच पिसा जीरा","1-1/2 छोटे चम्मच काली मिर्च","1 छोटा चम्मच बिना नमक वाला हर्ब सीज़निंग ब्लेंड"],
["मछली को पिघला लें। प्याज़ को छोटे टुकड़ों में काटें।","एक मध्यम आकार के बर्तन में 2 छोटे चम्मच तेल डालें और प्याज़ भूनें।","प्याज़ के भूरा हो जाने पर, लेकिन जले नहीं, चावल, 2 कप पानी, 1/2 छोटा चम्मच जीरा और 1/2 छोटा चम्मच काली मिर्च डालें।","ढककर मध्यम-धीमी आँच पर लगभग 20 मिनट पकाएँ।","एक कटोरे में मैदा, 1 छोटा चम्मच जीरा, 1 छोटा चम्मच काली मिर्च और बिना नमक वाली सीज़निंग डालें और अच्छी तरह मिलाएँ।","बचा हुआ तेल कड़ाही या फ्रायर में गरम करें। पिघली हुई मछली को पेपर टॉवल से सुखाएँ ताकि सारा अतिरिक्त पानी निकल जाए। मछली को मैदे के मिश्रण में लपेटें और गरम तेल में तलें।","गरम मछली को मसालेदार चावल के साथ परोसें।"],
["इस रेसिपी के लिए कोई भी सफ़ेद मछली चुनें।","जीरा एक ऐसा मसाला है जो पाचन में मदद करने के लिए जाना जाता है, लेकिन अगर इसे खाने की आदत न हो तो यह तेज़ लग सकता है। मात्रा को अपने स्वाद के अनुसार समायोजित करें।","चाहें तो मसालेदार चावल के साथ फ़िश फ्राई के साथ ये चीज़ें परोसी जा सकती हैं: काली मिर्च के साथ सिरके में भिगोया हुआ सफ़ेद प्याज़ या ताहिनी सॉस (2 बड़े चम्मच ताहिनी के साथ 1–2 छोटे चम्मच सफ़ेद सिरका, काली मिर्च और जीरा)।","कम प्रोटीन वाले आहार के लिए मछली को 4 की जगह 6 हिस्सों में बाँटें; इससे भोजन में प्रोटीन घटकर 17 ग्राम रह जाता है।"],
["3 प्रोटीन","3-1/2 स्टार्च","1/2 सब्ज़ी, मध्यम पोटैशियम","1 वसा"]),
(2289,"जौ और बीफ़ स्टू","जौ और बीफ़ स्टू डायलिसिस आहार में प्रोटीन पाने का एक गरम और स्वादिष्ट तरीका है। आप इस भरपेट भोजन का आनंद दोपहर या रात के खाने में ले सकते हैं।","6","1-1/4 कप",
["1 कप पर्ल बार्ली (जौ), बिना पकी हुई","1 पाउंड कम चर्बी वाला बीफ़ स्टू मीट","2 बड़े चम्मच सफ़ेद मैदा","1/4 छोटा चम्मच काली मिर्च","1/2 छोटा चम्मच नमक","2 बड़े चम्मच कैनोला तेल","1/2 कप प्याज़","1 बड़ा डंठल अजवाइन (सेलरी)","1 लहसुन की कली","2 मध्यम गाजर","2 तेज पत्ते","1 छोटा चम्मच Mrs. Dash® ओनियन हर्ब सीज़निंग"],
["जौ को 2 कप पानी में 1 घंटे के लिए भिगो दें।","प्याज़ और अजवाइन (सेलरी) को छोटे टुकड़ों में काटें। लहसुन की कली को बारीक काटें। गाजर को 1/4 इंच मोटे स्लाइस में काटें। बीफ़ को 1-1/2 इंच के टुकड़ों में काटें।","मैदा, काली मिर्च और स्टू मीट को एक प्लास्टिक बैग में रखें। स्टू मीट पर मैदा लगाने के लिए हिलाएँ।","एक भारी 4-क्वार्ट के बर्तन में तेल गरम करें और स्टू मीट को भूरा करें। मांस को बर्तन से निकाल लें।","मांस के रस में प्याज़, अजवाइन (सेलरी) और लहसुन को 2 मिनट तक भूनें और चलाएँ। 2 क्वार्ट पानी डालें और उबाल लें। मांस को वापस बर्तन में डालें। तेज पत्ते और नमक डालें। आँच धीमी कर दें।","जौ का पानी निथारकर धो लें, फिर बर्तन में डालें। ढककर 1 घंटे तक पकाएँ। हर 15 मिनट में चलाएँ।","1 घंटे बाद कटी हुई गाजर और Mrs. Dash® हर्ब सीज़निंग डालें। एक घंटा और धीमी आँच पर पकाएँ। चिपकने से रोकने के लिए ज़रूरत हो तो और पानी डालें।"],
["CKD (डायलिसिस पर नहीं) वाले कम प्रोटीन आहार के लिए, प्रति रेसिपी बीफ़ को घटाकर 8 ऑउंस कर दें। इससे प्रति सर्विंग प्रोटीन घटकर 14 ग्राम रह जाएगा।"],
["3 प्रोटीन","1 सब्ज़ी, मध्यम पोटैशियम","1 स्टार्च"]),
(2290,"ब्राउन शुगर एप्पल डिप","अपनी पसंदीदा किस्म के सेब के लिए झटपट डिप बनाएँ। सिर्फ़ 3 सामग्रियों के साथ ब्राउन शुगर एप्पल डिप जल्दी बनने वाला, आसान और किडनी के अनुकूल है।","8","2 बड़े चम्मच",
["8 ऑउंस क्रीम चीज़","3/4 कप ब्राउन शुगर, बिना दबाई हुई","1/2 छोटा चम्मच वनीला एक्सट्रैक्ट"],
["क्रीम चीज़ को नरम होने के लिए कमरे के तापमान पर 20 मिनट बाहर रखें।","हैंड मिक्सर से क्रीम चीज़, ब्राउन शुगर और वनीला को पूरी तरह मिलने तक मिलाएँ।","कटे हुए सेबों के साथ डिप का आनंद लें।"],
["यह डिप रेड डिलीशियस या ग्रैनी स्मिथ सेबों के साथ बहुत स्वादिष्ट लगता है।"],
["1/2 दूध","1/2 उच्च कैलोरी"]),
(2291,"लेमन थाइम चिकन","लेमन थाइम चिकन की किडनी के अनुकूल रेसिपी नरम, रसीली, स्वादिष्ट और मेहमानों के लिए भी खास है।","4","1 चिकन ब्रेस्ट",
["1 पाउंड बिना हड्डी और बिना त्वचा वाला चिकन ब्रेस्ट","2 बड़े चम्मच कैनोला तेल","1 कप प्याज़, छोटे टुकड़ों में कटा हुआ","14 ऑउंस कम सोडियम वाला चिकन ब्रॉथ","1/2 कप नींबू का रस","1 बड़ा चम्मच ताज़ी थाइम, कटी हुई","1/4 छोटा चम्मच काली मिर्च"],
["चिकन ब्रेस्ट को साफ़ करें और पतला होने तक पीटें।","एक बड़ी कड़ाही में चिकन को तेल में भूरा करें।","चिकन को प्लेट में निकालें और अलग रख दें।","कड़ाही में बचे तेल में प्याज़ डालें और प्याज़ के पारदर्शी होने तक भूनें।","ब्रॉथ, नींबू का रस, थाइम और काली मिर्च डालें। 10 मिनट तक पकाना जारी रखें।","चिकन को वापस कड़ाही में डालें और बीच-बीच में चलाते हुए 10 मिनट और पकाएँ।","गरमागरम परोसें।"],
["अगर चाहें तो पीटने से बचने के लिए मीट काउंटर से पतले कटे चिकन ब्रेस्ट खरीदें।","परोसने के सुझाव: हरी बीन्स के साथ चावल पर, या नूडल्स और गाजर के साथ, या सफ़ेद ब्रेड पर खुला सैंडविच बनाकर और उस पर ब्रॉथ का मिश्रण डालकर।","कम सोडियम वाले ब्रॉथ में प्रति सर्विंग 140 mg या उससे कम सोडियम होता है। घटे हुए सोडियम वाले ब्रॉथ में प्रति सर्विंग 220 से 600 mg सोडियम होता है।","पोटैशियम क्लोराइड वाले कम सोडियम ब्रॉथ से बचें, उसमें पोटैशियम बहुत अधिक होता है।","अगर आप कम प्रोटीन वाले आहार पर हैं, तो अपनी भोजन योजना के अनुसार मात्रा समायोजित करें।"],
["4 प्रोटीन","1/2 सब्ज़ी, कम पोटैशियम"]),
]
